"""Bilingual mathematical rewrites, independently scoped to the F10 author statements."""
from pathlib import Path
import importlib.util,copy
spec=importlib.util.spec_from_file_location('f08_rewrites',Path(__file__).parent.parent/'icml2023-bayesian/bayesian_rewrites.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
R={}
def add(i,zt,et,tex,zd,ed,za,ea,steps,role='proof',assessment='no_statement_error_recorded',scope=None):
 R[i]=dict(title=zt,title_en=et,statement_tex=tex,definitions=(zd,ed),assumptions=(za,ea),steps=steps,role=role,assessment=assessment,scope=scope)
def reuse(i,j,zt,et,role=None):
 R[i]=copy.deepcopy(m.R[j]);R[i].update(title=zt,title_en=et)
 if role:R[i]['role']=role
reuse('diff-universal','bnn-interaction','全部掩码精确重构','Exact reconstruction of every mask')
R['diff-universal']['scope']=('只证明原Eq3的精确全支持等号；近似显著和另列。','Only the exact full-support equality in source Eq. (3) is proved; the approximate salient sum is separate.')
reuse('diff-sparsity','bnn-sparsity','外引稀疏出现的条件范围','Scope of cited sparse emergence','statement_scope_explanation')
R['diff-sparsity']['definitions']=(r'原作者明确说在一组common conditions下证明稀疏，但本篇不列完整技术前提；普通Harsanyi游戏采用 $g(T)=v(x_T)$，$b=g(\varnothing)$。D章七性质逐项独立登记。',r'The author explicitly cites sparsity under common conditions but does not state their complete technical premises here. The ordinary Harsanyi game is $g(T)=v(x_T)$ with $b=g(\varnothing)$. All seven Section D properties are indexed separately.')
reuse('diff-taylor','bnn-taylor','Taylor 支持展开及任意 DNN 范围','Taylor support expansion and the arbitrary-DNN scope','partial_component')
reuse('diff-reference','bnn-reference','朝数据均值的参考距离','Reference distance toward the data mean')
reuse('diff-binary','bnn-binary','掩码触发的二值状态','Binary trigger states on masks','partial_component')
R['diff-binary']['assumptions']=(r'固定参考输入和基线；非零参考 $U_S=I_g(S)$。保留原全概念量词与零U问题，G3 Case1原S⊊T不是找到j∈S\T所需的关系。',r'Fix the reference input and baseline, with nonzero reference $U_S=I_g(S)$. Retain the source quantifier and zero-U issue. G.3 Case1 prints S⊊T, which does not justify finding j∈S\T.')
R['diff-binary']['steps'].append(('修正原证明的集合方向','Repair the set direction in the source proof',r'不触发情形是 $S\not\subseteq T$，因此有 $j\in S\setminus T$。这与原Case1印式 $S\subsetneq T$ 不同；原结论的非零域二值性质仍由真正掩码游戏证明。Eq21/24原 $r_i/b_i$ 交替保留在原文，重写统一输入基线r。',r'The inactive case is $S\not\subseteq T$, which supplies j∈S\T. This differs from printed Case1 S⊊T. The binary conclusion on its nonzero domain follows from the actual masked game. Original Eqs. (21)/(24) alternate r_i and b_i; the rewrite consistently uses input baseline r.'))
reuse('diff-linear-representation','bnn-linear-representation','连续触发线性重构','Linear reconstruction from continuous triggers','partial_component')
R['diff-linear-representation']['scope']=('全有限支持、每个所用非零固定参考系数下的精确重构；不证明显著截断误差很小，也不覆盖零参考而当前非零交互。','Exact reconstruction with full finite support and nonzero fixed reference coefficients for all used terms. This does not prove a small salient truncation error or cover zero reference dividends that become nonzero.')
add('diff-salient-reconstruction','显著截断的精确余项','The exact residual of salient truncation',r'g(T)-\sum_{S\in\Omega,\,S\subseteq T}I_g(S)=\sum_{S\subseteq T,\,S\notin\Omega}I_g(S)',
 r'$\Omega\subseteq2^N$ 为选择的显著族；原文的“≈”未给容许误差、阈值或统一尾和条件。','The salient family is Ω⊆2^N. The source approximation gives no tolerance, threshold or uniform tail-sum condition.',
 '有限游戏；保留源近似措辞，不把经验稀疏当作逐游戏假设。','Use a finite game and retain the source approximation wording; empirical sparsity is not a per-game premise.',[
 ('分开保留项与遗漏项','Separate retained and omitted terms',r'完整重构按 $S\in\Omega$ 与 $S\notin\Omega$ 分割。相减后即得所列精确余项。因而 $|R_T|\le\sum_{S\subseteq T,S\notin\Omega}|I_g(S)|$。输出基线由空交互 $I_g(\varnothing)=b$ 保留，若空项不在Ω则也是余项。',r'Split complete reconstruction by membership in Ω and subtract to obtain the exact residual. Thus $|R_T|\le\sum_{S\subseteq T,S\notin\Omega}|I_g(S)|$. The output baseline is the empty dividend b; excluding it from Ω places it in the residual.'),
 ('核查近似所需的额外控制','Check the additional control needed for approximation','只有右侧尾和小才得到定量近似。源未指定这样的界，不能从重构恒等式自动证明少量显著概念始终近似全部掩码。该项解释原近似范围，不声称外引带完整前提的定理已被反驳。','A quantitative approximation requires a small tail sum. No such bound is specified here, so reconstruction alone does not show that few salient concepts approximate every mask. This records the scope of the approximation rather than refuting a cited theorem with its full premises.')],role='statement_scope_explanation',assessment='scope_under_review')
add('diff-moments','最低阶绝对触发的真实 Gaussian 矩','Actual Gaussian moments of the lowest absolute trigger',r'Z=1+\epsilon,\quad E|Z|>1,\quad \operatorname{Var}|Z|=1+q-(E|Z|)^2<q\quad(q>0)',
 r'选单坐标 $x=1,r=0,\tau=1$、$\epsilon\sim\mathcal N(0,q)$。原J为 $\operatorname{sign}(1+\epsilon)(1+\epsilon)=|1+\epsilon|$，不是有符号最低交互I。','Take one coordinate x=1,r=0,τ=1 with ε~N(0,q). Source J is sign(1+ε)(1+ε)=|1+ε|, rather than the signed lowest dividend I.',
 '正Gaussian方差q，保留完整尾部。G2要求|ε|≤τ并忽略越界，与非退化Gaussian几乎处处有界不相容；它是近似步骤。','Use positive Gaussian variance q and retain the full tails. G.2 assumes |ε|≤τ and ignores crossing, which is incompatible with an almost-sure bound for a nondegenerate Gaussian; it is an approximation.',[
 ('保留绝对值和实际分布','Retain the absolute value and actual law',r'$Z\sim\mathcal N(1,q)$，$E Z=1$。$|Z|-Z\ge0$，在 $Z<0$ 时严格正；正方差Gaussian在该区间有正概率，故 $E|Z|=1+E(|Z|-Z)>1$。实际Lean用Gaussian对Lebesgue的等价性与连续非零函数证明严格积分正。',r'Z~N(1,q) and EZ=1. The difference |Z|−Z is nonnegative and strictly positive for Z<0, a positive-probability Gaussian event. Hence E|Z|=1+E(|Z|−Z)>1. Lean proves strict positivity using Gaussian/Lebesgue equivalence and continuity of a nonzero function.'),
 ('用二阶矩反驳原方差','Refute the printed variance using the second moment',r'$|Z|^2=Z^2$ 且 $EZ^2=1+q$，所以 $\operatorname{Var}|Z|=1+q-(E|Z|)^2<q$。原Eq5在|S|=1给均值1、方差q，两子句在真实完整Gaussian模型均失败。若仅分析有符号 $Z$，这些式子成立；不能把J换成Z修命题。',r'Since |Z|²=Z² and EZ²=1+q, Var|Z|=1+q−(E|Z|)²<q. For one-coordinate support, Eq. (5) states mean1 and varianceq, so both exact clauses fail under the full Gaussian model. Those formulas hold for signed Z, but replacing J by Z would change the statement.')],role='counterexample',assessment='refuted')
add('diff-general-moments','一般绝对触发的乘积矩','Product moments for general absolute triggers',r'EJ=\prod_i E|1+s_i\epsilon_i/\tau|^{\pi_i},\quad \operatorname{Var}J=\prod_i E|1+s_i\epsilon_i/\tau|^{2\pi_i}-(EJ)^2',
 r'$\pi_i\ge1$ 为支持上的整数次数，$s_i=\operatorname{sign}(x_i-r_i)$、$x_i-r_i=s_i\tau$。独立Gaussian坐标给真实绝对幂乘积J。原\|π\|1总次数与支持阶数|S|不同。','Each support degree π_i is a positive integer, and x_i−r_i=s_iτ with s_i=sign(x_i−r_i). Independent Gaussian coordinates give the actual absolute-power product J. Total degree ||π||₁ differs from support order |S|.',
 'τ>0与独立Gaussian；Gaussian任意有限幂有二阶矩。不删越界尾，不将一般阶≪τ近似当作精确事件。','Assume τ>0 and independent Gaussian coordinates, whose finite integer powers have second moments. Do not remove crossing tails or turn the general-degree ≪τ approximation into an exact event.',[
 ('应用真正独立乘积矩','Apply the actual independent-product moments',r'映射 $1+s_i\epsilon_i/\tau$ 同律于N(1,q)，q=σ²/τ²。可测函数变换保持独立；Gaussian有限幂L2可积，故积分可因子化，得陈述中的真实folded矩。共享 Gaussian 库直接处理全部这些条件。','Each affine coordinate has law N(1,q), q=σ²/τ². Measurable transformations preserve independence and Gaussian finite powers are L2, so the product integral factors into the folded moments displayed. The shared Gaussian library discharges these conditions.'),
 ('定位原绝对值到有符号的错步','Locate the incorrect absolute-to-signed transition',r'G2 Eq14–18在小扰动语境把 $|1+s\epsilon/\tau|^{\pi_i}$ 改成 $(1+\epsilon/\tau)^{\pi_i}$。当π_i奇数时不相等；单坐标π=1已由前条实际均值与方差反例同时否定Eq6精确读法。偶数幂时绝对值可精确消去，故不将所有整数次数一律判错。',r'G.2 Eqs. (14)–(18) replace |1+sε/τ|^{π_i} by (1+ε/τ)^{π_i} under a small-noise approximation. For odd powers these differ; the actual one-coordinate degree1 mean and variance counterexample refutes the exact reading of Eq. (6). For even powers the absolute value cancels exactly, so not every integer degree is classified as erroneous.')],role='partial_proof_with_refuted_clause',assessment='partially_refuted')
add('diff-product','独立乘积方差平方的原式反例','Counterexample to the squared-variance product formula',r'E\prod_iX_i=\prod_iEX_i,\quad\operatorname{Var}\prod_iX_i=\prod_i((EX_i)^2+\operatorname{Var}X_i)-\prod_i(EX_i)^2',
 'X_i为独立、具有有限二阶矩的实随机变量；原Proposition1在括号内印的是Var[X_i]²，原式原样保留。','The X_i are independent real random variables with finite second moments. Source Proposition1 prints Var[X_i]² inside the parentheses; that expression is retained in the original field.',
 '独立与L2用于正确乘积矩；反例只有一个Gaussian因子，独立条件自动成立。','Independence and L2 suffice for the correct product moments. The counterexample has one Gaussian factor, making independence automatic.',[
 ('证明有效均值与正确方差','Prove the valid mean and correct variance',r'独立给 $E\prod X_i=\prod EX_i$ 和 $E(\prod X_i)^2=\prod EX_i^2$。代入 $EX_i^2=(EX_i)^2+\operatorname{Var}X_i$ 并减去均值平方，得到陈述式；不是把Var本身平方。',r'Independence yields E∏X_i=∏EX_i and E(∏X_i)²=∏EX_i². Substitute EX_i²=(EX_i)²+VarX_i and subtract the squared product mean. This uses variance itself, without squaring it.'),
 ('构造原方差子句的真实反例','Construct an actual counterexample to the source variance clause','取k=1、X~N(0,2)。真实均值0、方差2，而原打印右式为0+2²−0=4。PaperDifficulty绑定实际Gaussian integral/variance，而非只证明2≠4。紧接源Eq12却使用正确1+σ²/τ²，前后差异保留。均值子句仍成立。','Take k=1 and X~N(0,2). Its actual mean is0 and variance2, while the printed RHS is0+2²−0=4. PaperDifficulty binds the actual Gaussian integral and variance rather than merely proving 2≠4. The following source Eq. (12) uses the correct 1+σ²/τ²; the inconsistency is retained. The mean clause remains valid.')],role='partial_proof_with_refuted_clause',assessment='partially_refuted')
add('diff-order-variance-argument','加权交互方差所需的协方差','Covariances needed for a weighted dividend variance',r'\operatorname{Var}\left(\sum_\pi a_\pi J_\pi\right)=\sum_{\pi,\rho}a_\pi a_\rho\operatorname{Cov}(J_\pi,J_\rho)',
 '先取固定系数、有限和与有限二阶矩；原U包含moving sign时系数也是随机变量，不能移出期望。','Begin with fixed coefficients, a finite sum and finite second moments. When source U has moving signs, the coefficients are random too and cannot be pulled out of expectations.',
 '保留usually chaotic、roughly consider近似措辞。作者未给系数概率律、跨阶幅值界或协方差控制。','Retain “usually chaotic” and “roughly consider”. No coefficient law, cross-order amplitude bound or covariance control is supplied.',[
 ('保留全部交叉项','Retain every cross term','展开中心化有限和的平方后积分即为协方差双和。共享同一噪声的不同次数项通常相关，异号系数还可抵消；单项J方差增长不直接推出其加权和I的方差增长。','Expand the square of the centered finite sum and integrate to obtain the covariance double sum. Terms of different degrees under the same noise are generally correlated and signed coefficients can cancel. Growing component variances do not directly prove growing dividend variance.'),
 ('区分近似解释与完整定理','Distinguish approximate interpretation from a complete theorem','原Eq5/6的J矩错误另列；即使将它们修成真实folded矩，也仍缺上述叠加条件和不同支持之间的比较结构。此条完成原论证的范围分析，不报任意DNN的统一高阶不稳定性机器定理。','The J-moment errors in Eqs. (5)/(6) are separate issues. Repairing them to actual folded moments still leaves the missing superposition conditions and comparisons between different supports. This is a scope analysis of the argument, not a machine theorem of universal high-order instability.')],role='statement_scope_explanation',assessment='scope_under_review')
add('diff-regression','真实独立 Gaussian 回归最优与丢均值反例','Actual independent-Gaussian optimum and the omitted-mean counterexample',r'w_i^*=\frac{y^*}{1+\sum_j\mu_j^2/d_j}\frac{\mu_i}{d_i}',
 r'f_i独立Gaussian，均值μ_i、真实方差d_i>0。$K=E[ff^\top]=\mu\mu^\top+\operatorname{diag}d$。原文先写N(μ,Σ²)，又写Σ=diag(σ_i²)，与K=μμᵀ+Σ²有方差/方差平方记号冲突。','The f_i are independent Gaussian features with means μ_i and true variances d_i>0. K=E[ffᵀ]=μμᵀ+diag d. The source writes N(μ,Σ²), then Σ=diag(σ_i²) and K=μμᵀ+Σ², creating a variance-versus-squared-variance notation conflict.',
 '固定特征分布、平方损失与正真实方差。主反例双方差1，使Σ=Σ²=I，两种原记号读法相同。','Fix the feature distribution and squared loss, with positive true variances. Both variances are1 in the main counterexample, so Σ=Σ²=I under either source notation.',[
 ('展开真实期望并计算 Gram 矩阵','Expand the actual expectation and compute the Gram matrix',r'$L(w)=E(y^*-w^\top f)^2=(y^*-\mu^\top w)^2+\sum_i d_iw_i^2$，因为不同特征协方差0。因此梯度为 $2(Kw-y^*\mu)$。独立Gaussian的均值/二阶矩由实际分布证明，并非假设这些期望等式。',r'L(w)=E(y*−wᵀf)²=(y*−μᵀw)²+Σ_i d_iw_i², because distinct-feature covariances vanish. Thus the gradient is2(Kw−y*μ). The actual Gaussian laws establish the feature means and second moments rather than assuming the required expectation equalities.'),
 ('证明唯一最优并保留均值因子','Prove the unique optimum and retain the mean factor',r'令h=1+∑μ_j²/d_j>0，取w_i*=y*μ_i/(d_i h)，直接验Kw*=y*μ。对任意z≠0，zᵀKz=(μᵀz)²+∑d_i z_i²>0；展开L(w)-L(w*)=(w-w*)ᵀK(w-w*)>0，得到真实全局唯一argmin。Step2比例 |w_i/w_j|=|μ_i/d_i|/|μ_j/d_j| 有定义时正确；Step3不能丢μ_i。',r'Let h=1+Σμ_j²/d_j>0 and w_i*=y*μ_i/(d_i h). Verify Kw*=y*μ. For z≠0, zᵀKz=(μᵀz)²+Σd_i z_i²>0. Completing the square gives L(w)−L(w*)=(w−w*)ᵀK(w−w*)>0, establishing the unique global argmin. Step2’s ratio |w_i/w_j|=|μ_i/d_i|/|μ_j/d_j| is correct where defined; Step3 cannot discard μ_i.'),
 ('给出没有协方差记号分歧的反例','Give a counterexample without covariance-notation ambiguity',r'取两独立Gaussian，μ=(1,2)、d=(1,1)、y*=1。K=[[2,2],[2,5]]、detK=6，唯一最优w*=(1/6,1/3)。真实比值1/2，原Step3逆方差比值为1。机器声明绑定Measure.pi上的真实期望损失和所有其他w的严格更大损失，同时检查这两个比值。',r'Take independent Gaussians with μ=(1,2), d=(1,1), y*=1. Then K=[[2,2],[2,5]], detK=6 and the unique optimum is (1/6,1/3). The actual ratio is1/2, whereas Step3’s inverse-variance ratio is1. The machine statement binds the actual expected loss on Measure.pi, strict inequality for every other weight vector and the conflicting ratios.')],role='partial_proof_with_refuted_clause',assessment='partially_refuted')
add('diff-multiorder','多阶上下文平均与原组合式反例','Context averaging and counterexamples to the printed combinatorial formula',r'I^{(m)}(i,j)=\frac1{\binom{n-2}m}\sum_{l=0}^m\binom{n-2-l}{m-l}\sum_{L\subseteq N\setminus\{i,j\},\,|L|=l}I_g(L\cup\{i,j\})',
 r'i≠j∈N，R=N\{i,j}、n=|N|、0≤m≤n−2；m为上下文基数，|L|+2为概念支持阶数。$\Delta g(i,j,S)=g(Sij)-g(Si)-g(Sj)+g(S)$。上式是重写正确关系，原Eq25错式保留。',r'Let i≠j belong to N, R=N\{i,j}, n=|N| and 0≤m≤n−2. The context cardinality is m, while the concept support size is |L|+2. Define Δg(i,j,S)=g(Sij)−g(Si)−g(Sj)+g(S). The displayed rewrite is the correct relation; original Eq. (25) is retained unchanged.',
 '有限游戏和合法上下文平均；不要求输出基线为0。原最后等式有两处独立错误，不能把修过的式子当原命题证明。','Use a finite game and a defined context average; the output baseline may be nonzero. The original final equality has two independent errors, so a repaired formula is not a proof of the original statement.',[
 ('先证明每个上下文的真实差分分解','First prove the actual difference decomposition for each context',r'重构四个g值并相消后，只有同时含i和j的交互留下，得 $\Delta g(i,j,S)=\sum_{L\subseteq S}I_g(L\cup\{i,j\})$。实际Lean从higherMarginal重构证明这一步，并在全部m大小上下文上取准确平均。',r'Reconstruct all four game values and cancel. Only dividends containing both i and j remain, giving Δg(i,j,S)=Σ_{L⊆S}I_g(L∪{i,j}). Lean derives this from higherMarginal reconstruction and takes the exact average over all size-m contexts.'),
 ('逐支持数包含它的上下文','Count the contexts containing each support',r'固定|L|=l的L⊆R，包含L的m大小S由R\L选择m−l个变量，数目是 choose(n−2−l,m−l)，而非原choose(n−2,m−l)。按l分组的内和应|L|=l，不是原最后|L|=m。重写公式的计数在此完整给出；Lean当前形式化真实未分组上下文等式及下面两独立原式反例，不宣称一般按l分组计数已机器完成。',r'For a fixed L⊆R of size l, an m-element context containing L chooses m−l elements from R\L, giving choose(n−2−l,m−l), not choose(n−2,m−l). The grouped inner sum must use |L|=l rather than the final printed |L|=m. This supplies the complete counting proof of the rewritten formula. Lean currently proves the exact ungrouped context identity and the two separate source counterexamples below; general grouping by l is not claimed machine-complete.'),
 ('分别反驳最后下标和组合系数','Refute the final index and combinatorial coefficient separately',r'N={1,2,3},i=1,j=2,m=1，取真实masked score v=z1z2、x=1,r=0。Δ平均为1，原|L|=m只取L={3}，I({1,2,3})=0，打印右式0。再取N4,m2,v=z1z2z3；真实平均1。即使只修内层为|L|=l，唯一L={3}对应原系数 choose(2,1)/choose(2,2)=2，使右式2。两个Lean反例均绑定坐标多项式掩码游戏，而非任意指定交互值。',r'For N={1,2,3}, i=1,j=2,m=1 use the actual masked score v=z1z2 with x=1,r=0. The mean difference is1, while printed |L|=m selects only L={3}, whose three-way dividend is0, giving RHS0. Next take N of size4,m2,v=z1z2z3. The true mean is1. Even after repairing only the inner index, the sole L={3} gets the source coefficient choose(2,1)/choose(2,2)=2, producing RHS2. Both Lean counterexamples use masked coordinate polynomials rather than arbitrarily assigned dividends.')],role='partial_proof_with_refuted_clause',assessment='partially_refuted')
add('diff-kappa-conversion','κ 的跨样本约分反例','Counterexample to cancellation across samples in kappa',r'\kappa_I=\frac{E_x[|U_x|E_\epsilon|C_x(x+\epsilon)-C_x(x)|]}{E_x[|U_x||C_x(x)|]}',
 r'每个参考样本x有固定非零U_x=I(S|x)，C_x(x\prime)=I(S|x\prime)/U_x。跨噪声固定，但跨数据通常变化。取一坐标等概率数据x=−1,1，均值0、方差1，τ1、r0，v(t)=max(t+1/2,0)。','Each reference sample x has a fixed nonzero U_x=I(S|x), with C_x(x′)=I(S|x′)/U_x. It is fixed across noise but generally varies across data. Take equally likely one-coordinate data x=−1,1, with mean0, variance1, τ1,r0 and v(t)=max(t+1/2,0).',
 '真实单ReLU与完整Gaussianε=σZ，Z~N(0,1)，σ=m0/[8(1+m0)]，m0=E|Z|>0。机器证明0<σ<1/8；不声称固定σ=.1已机器验证。','Use an actual single ReLU and the full Gaussian ε=σZ, Z~N(0,1), with σ=m0/[8(1+m0)] and m0=E|Z|>0. Lean proves 0<σ<1/8; fixed σ=.1 is not claimed machine-verified.',[
 ('连上真实 singleton Harsanyi 与原参考规则','Connect the actual singleton Harsanyi dividend and reference rule',r'两个数据样本按“朝均值移动τ”都给r=0，裁剪不改变r。输出基线b=v(0)=1/2非零。单例掩码交互是I(x+ε)=v(x+ε)−v(0)，故参考U_low=−1/2,U_high=1，C_x(x)=1。实际Lean的singletonGame→interaction_singleton明确验证这条适配。',r'Both samples produce r=0 by moving distance τ toward the mean; clipping changes nothing. The nonzero output baseline is b=v(0)=1/2. The singleton masked dividend is I(x+ε)=v(x+ε)−v(0), giving U_low=−1/2,U_high=1 and C_x(x)=1. Lean explicitly proves the singletonGame-to-interaction_singleton adaptation.'),
 ('证明完整 Gaussian 的两个尾积分界','Prove two tail-integral bounds for the full Gaussian',r'令A_low=E(ε−1/2)_+，A_high=E|max(3/2+ε,0)−3/2|，m=E|ε|=σm0，q=Eε²=σ²。由(z−a)_+≤z²/(4a)得A_low≤q/2。恒等式 |max(3/2+ε,0)−3/2|=|ε|−(−ε−3/2)_+ 给A_high≥m−q/6。所有被积函数L1由Gaussian L2和max/abs性质证明，没有删除Gaussian尾。',r'Put A_low=E(ε−1/2)_+, A_high=E|max(3/2+ε,0)−3/2|, m=E|ε|=σm0 and q=Eε²=σ². The bound (z−a)_+≤z²/(4a) gives A_low≤q/2. The identity |max(3/2+ε,0)−3/2|=|ε|−(−ε−3/2)_+ gives A_high≥m−q/6. Gaussian L2 and max/absolute-value closure establish L1 for every integrand; no tails are discarded.'),
 ('计算两条源 κ 表达式并严格分离','Compute and strictly separate the two source kappa expressions',r'原交互比值κ_I=2(A_low+A_high)/3；原无权触发比值κ_C=A_low+A_high/2，实际normalizedCoefficient积分与此式相等也有Lean证明。于是κ_I−κ_C=(A_high−2A_low)/6≥(m−7q/6)/6>0。选定σ<m0/8且σ>0使m>7q/6。原等号错在跨x省掉|U_x|；正确式是所列加权比值。',r'The original dividend ratio is κ_I=2(A_low+A_high)/3; the printed unweighted coefficient ratio is κ_C=A_low+A_high/2. Lean also proves equality between the actual normalizedCoefficient integral and this latter expression. Thus κ_I−κ_C=(A_high−2A_low)/6≥(m−7q/6)/6>0. The chosen positive σ<m0/8 gives m>7q/6. The source equality incorrectly removes |U_x| across data; the correct expression is the weighted ratio displayed.')],role='counterexample',assessment='refuted')
# Seven separately indexed properties, with the original nonempty dummy scope.
props={
'efficiency':('效率与任意输出基线','Efficiency with an arbitrary output baseline',r'g(N)=\sum_{S\subseteq N}I_g(S)','取固定有限游戏g与总体N，空交互I_g(∅)=b。','Fix a finite game g and universe N, with empty dividend I_g(∅)=b.','交换双子集和','Exchange the double subset sum',r'展开交互后，每个g(T)的系数为∑_{T⊆S⊆N}(-1)^{|S|-|T|}，除T=N外均为0；T=N时为1。完整效率因此包含b，不擅自改成非空和。',r'After expansion, g(T) has coefficient Σ_{T⊆S⊆N}(−1)^{|S|−|T|}, which vanishes except at T=N, where it is1. Efficiency includes b and is not silently converted to a nonempty sum.'),
'linearity':('交互对奖励的线性','Linearity in the reward',r'I_{g+h}(S)=I_g(S)+I_h(S)','g,h为同总体的实游戏；原u=v+w是奖励相加而非网络参数相加。','The real games g,h share a universe. Source u=v+w adds rewards, not network parameters.','在有限和中分配乘法','Distribute multiplication in the finite sum',r'每个(-1)^{|S|-|T|}(g(T)+h(T))分成两项；有限求和分配即得式子，包括空S及其基线之和。',r'Distribute each (−1)^{|S|−|T|}(g(T)+h(T)) and separate the finite sums. This includes empty S and the sum of output baselines.'),
'dummy':('非空上下文 Dummy 的消去','Dummy cancellation for nonempty contexts',r'I_g(S\cup\{i\})=0\quad(S\ne\varnothing)',r'原前提∀U⊆N\{i},g(Ui)=g(U)+g({i})，原结论∅≠S⊊N\{i}。前提取U=∅强制b=0，但没有额外补b=0。',r'The source premise is g(Ui)=g(U)+g({i}) for every U⊆N\{i}; the conclusion uses nonempty strict S⊊N\{i}. Setting U=∅ forces b=0 from the original premise, without adding it.','将插入变量配成常数差分','Pair subsets into a constant insertion difference',r'I_g(Si)=I_{U↦g(Ui)-g(U)}(S)=I_{constant g({i})}(S)。非空S的常数交互为0。这里非空条件来自作者，故没有旧论文空上下文单例反例。',r'I_g(Si)=I_{U↦g(Ui)−g(U)}(S)=I_{constant g({i})}(S), which vanishes for nonempty S. The author supplies nonemptiness, so the empty-context counterexample from another paper does not apply.'),
'symmetry':('变量对称性','Symmetry between variables',r'I_g(Si)=I_g(Sj)','i,j不在S；原交换对称奖励前提在所有所需U⊆S成立。','The variables i,j are outside S; the reward-symmetry premise holds for every required U⊆S.','比较两条插入差分','Compare the two insertion differences',r'分别写I_g(Si)=I_{U↦g(Ui)-g(U)}(S)与j版本。前提g(Ui)=g(Uj)使每个被积奖励相同，有限交互合同性即给等式。',r'Write each dividend as the interaction of its insertion difference. The premise g(Ui)=g(Uj) equates every used reward difference, so finite interaction congruence yields the equality.'),
'anonymity':('双射重命名保持交互','Bijection relabeling preserves dividends',r'I_{g\circ\pi^{-1}}(\pi(S))=I_g(S)','π为变量双射，并在奖励与支持上同步重命名。','The variable map π is a bijection, applied consistently to both reward and coalition.','对子集求和建立双射','Establish a bijection between the subset sums',r'U⊆π(S)经π^{-1}对应T⊆S；双射保持|U|=|T|和|π(S)|=|S|，故交替系数与奖励均对应。原φ中的匿名重标不能仅改符号不改g。',r'Each U⊆π(S) corresponds to T=π^{-1}(U)⊆S. Cardinalities and rewards match, preserving every alternating term. Relabeling must transform g as well as its symbols.'),
'recursion':('附录局部递归差分','The appendix local recursive difference',r'I_g(Si)=I_{U\mapsto g(Ui)}(S)-I_g(S)','i∉S；原I(S|i present)是强制i出现的另一个上下文游戏。','Assume i∉S. Source I(S|i present) is the interaction in a different game with i forced present.','把每个T与Ti配对','Pair every T with Ti',r'Si的子集分成T⊆S和Ti。两者符号相反，得∑_{T⊆S}(-1)^{|S|-|T|}[g(Ti)-g(T)]，再按交互线性拆成右式。附录Eq2与正文Eq2不合并编号。',r'Partition the subsets of Si into T⊆S and Ti. Their signs are opposite, giving Σ_{T⊆S}(−1)^{|S|−|T|}[g(Ti)−g(T)]. Linearity separates the right-hand side. Appendix Eq. (2) is a local alias distinct from main Eq. (2).'),
'distribution':('纯 AND 的单一交互分布','A pure AND has a single dividend',r'g(T)=c\,1[A\subseteq T]\ \Longrightarrow\ I_g(S)=c\,1[S=A]','A为固定支持，c∈ℝ；源v_T是纯AND游戏，并非任意网络的输出。','Fix support A and amplitude c∈ℝ. Source v_T denotes a pure AND game, not an arbitrary network output.','从单个系数重构纯 AND','Reconstruct the pure AND from one coefficient',r'只在A放系数c，其他支持放0；子集重构等于c·1[A⊆T]。Möbius反演唯一性遂给I_g(S)=c·1[S=A]。若A=∅，它是常数游戏，唯一空项为c，仍与任意b约定相容。',r'Assign coefficient c only at A. Subset reconstruction gives c·1[A⊆T]. Möbius inversion uniqueness yields I_g(S)=c·1[S=A]. For A=∅ the game is constant with sole empty coefficient c, consistent with arbitrary output baselines.')}
for k,(zt,et,tex,zd,ed,st,est,zbody,ebody) in props.items():
 add('diff-'+k,zt,et,tex,zd,ed,'严格采用原性质的局部前提，不从其他篇补假设。','Use the exact local premises of this property; no premise is imported from another paper.',[(st,est,zbody,ebody)])
R['diff-binary']['steps'][1]=('在原非零范围归一化','Normalize on the original nonzero domain',r'U_S≠0时，支持律除以U_S给C_S(x_T)=1[S⊆T]。正文PDF6直接用所有变量保留/任一被遮罩说明二值，附录G3给Taylor证明。常数网络非空U_S=0时原比值0/0；本条不擅自加源未写的扩展值。',r'For U_S≠0, divide the support law by U_S to obtain C_S(x_T)=1[S⊆T]. Main PDF6 explains the all-present/any-masked binary rule; G.3 supplies the Taylor-based proof. A constant network has zero nonempty U_S and source ratio0/0. No unstated extension value is added.')
for n in ['diff-linear-representation']:
 R[n]['steps']=[tuple(t.replace('Lemma2.1','Theorem2').replace('Lemma 2.1','Theorem 2') if isinstance(t,str) else t for t in s) for s in R[n]['steps']]
R['diff-reference']['steps'][1]=('核查局部小扰动条件','Check the local small-noise conditions',r'G2最低阶写|ε_i|≤τ，一般阶写|ε_i|≪τ；本篇理论采用完整Gaussian噪声而没有截断分布。正方差Gaussian不能几乎处处满足有界条件，故这些是忽略尾部的近似步骤。固定参考系数乘有符号最低交互可有精确矩，但原Theorem3陈述J自身，不能换对象。',r'G.2 writes |ε_i|≤τ for lowest degree and |ε_i|≪τ for general degree, while the stated noise law is a full Gaussian rather than a truncated one. A positive-variance Gaussian cannot satisfy a bounded condition almost surely. These are therefore tail-neglect approximations. A signed lowest dividend with a fixed reference coefficient can have exact moments, but source Theorem3 concerns J itself and cannot be replaced by that object.')
# Definitions and experimental aggregates have source-material rewrites, not fabricated proofs.
def material(i,zt,et,tex,zd,ed,zbody,ebody):
 add(i,zt,et,tex,zd,ed,'按原定义及其分母有定义范围阅读；不将指标或有限图表当成普遍定理。','Read the source definition on its defined domain; a metric or finite plot is not a universal theorem.',[(zt,et,zbody,ebody)],role='source_material')
material('diff-interaction','固定掩码游戏的交互定义','Dividend definition for a fixed masked game',r'I_g(S)=\sum_{T\subseteq S}(-1)^{|S|-|T|}g(T)',r'固定样本x、输入参考r、变量总体N。g(T)=v(x_T)，输出基线b=g(∅)，g0=g−b。',r'Fix x, input reference r and universe N. Define g(T)=v(x_T), output baseline b=g(∅) and g0=g−b.',r'原Eq1为普通Harsanyi变换，包含空集。非空交互在中心化后不变，空交互从b变为0。基线向量原b_i在重写映射成r_i，区别标量输出b。',r'Source Eq. (1) is the ordinary Harsanyi transform, including the empty coalition. Centering preserves every nonempty dividend and changes the empty dividend from b to0. Source input baseline b_i is mapped to r_i, distinct from scalar output baseline b.')
material('diff-concept-order','支持阶数与总次数','Support order and total degree',r'\operatorname{order}(S)=|S|,\quad\|\pi\|_1=\sum_i\pi_i',r'S为输入变量支持；π为该支持上可能不同的正整数次数。',r'S is the input-variable support; π gives possibly different positive integer degrees on that support.',r'三变量概念S的阶数恒3，但单项式次数可以是(1,1,1)或(2,3,1)，总次数分别3、6。附录F的m是上下文基数，不能把m、|S|、总次数互换。',r'A three-variable support has order3, while degree vectors (1,1,1) and (2,3,1) have total degrees3 and6. Appendix F’s m denotes context cardinality, which is distinct from both support order and total degree.')
material('diff-trigger-definition','固定参考系数的商触发','Quotient trigger with a fixed reference coefficient',r'U_S=I_g(S),\quad C_S(x\prime)=I_{g_{x\prime}}(S)/U_S',r'g为参考样本游戏，g_{x′}为当前输入在同一固定基线下的游戏；回归优化时固定C而优化另一个权重向量。',r'g is the reference-input game and g_{x′} is the current-input game with the same fixed baseline. Regression holds C fixed while optimizing a separate weight vector.',r'当U_S≠0时I当前=U_SC当前是定义的精确恒等。任意变换后的C不必二值；二值是参考掩码子域的定理。原式对U_S=0未定义，不能用0/0约分为1；若当前I非零，乘固定零U根本无法表达。',r'For U_S≠0, current I=U_S times current C is exact by definition. A trigger under an arbitrary transformation need not be binary; binary behavior is a theorem only on reference masks. The source quotient is undefined for U_S=0 and0/0 cannot cancel to1. A nonzero current dividend cannot be expressed using a fixed zero U.')
material('diff-order-variance-metrics','噪声平均及标准差稳定度','Noise averages and standard-deviation stability',r'E^{(s)}=E_xE_{|S|=s}|E_\epsilon I_S|,\quad V^{(s)}=E_xE_{|S|=s}\operatorname{Var}_\epsilon I_S,\quad E^{(s)}/\sqrt{V^{(s)}}',r'先对每个样本/概念取Gaussian噪声矩，再对同阶支持和样本平均。',r'First take Gaussian-noise moments for each sample and concept, then average across same-order supports and samples.',r'平均V后的平方根不等于先逐项开方平均。原图2相对稳定度分母为标准差√V；F08的E/Var是另一指标，不能合成一个规范概念。零V时比值无源约定。图2有限模型的趋势不是由指标定义推出的定理。',r'The square root of the averaged V is not the average of component square roots. Figure2 uses standard deviation √V, whereas F08’s E/Var is a different metric and must not share the same canonical concept. The source gives no zero-V convention. A trend across finite models is not implied by the metric definition.')
material('diff-training-metrics','类别 β 与扰动 κ 指标','Class consistency beta and perturbation kappa',r'\beta(S)=E_c\frac{|E_{x\in X_c}I(S\mid x)|}{\operatorname{Std}_{x\in X_c}I(S\mid x)}',r'X_c为类别c样本，X为总样本；β对数据变化取标准差，κ对每个数据输入另取噪声绝对变化。',r'X_c is the class-c sample set and X the full sample set. Beta uses standard deviation across data, while kappa additionally averages absolute noise changes for each input.',r'β先按类别计算均值/标准差再平均类别；不是Gaussian噪声E/Var。κ的I定义及打印C等号保留在原文，后者单独列为diff-kappa-conversion数学目标。零标准差和零幅值平均分母都需源未提供的边界约定，不能由Lean总除法补齐。',r'Beta computes a mean/standard-deviation ratio within each class before averaging classes; it differs from Gaussian-noise E/Var. The I definition of kappa and the printed C equality are retained in the original field; the equality has separate mathematical target diff-kappa-conversion. Zero standard deviations and zero mean magnitudes require boundary conventions absent from the source, which Lean’s total division does not supply.')
material('diff-multiorder-definition','固定上下文基数的平均','Average at a fixed context cardinality',r'I^{(m)}(i,j)=E_{S\subseteq N\setminus\{i,j\},\,|S|=m}\Delta g(i,j,S)',r'R=N\{i,j}；上下文S从R中均匀选m个变量，分母choose(|R|,m)。',r'R=N\{i,j}. Choose size-m contexts uniformly from R, with denominator choose(|R|,m).',r'平均存在需0≤m≤|R|。每个上下文差分包含I(Lij)的多个支持阶数|L|+2，0≤|L|≤m；因此m阶多阶交互不等于只取某个固定概念阶数。原F定义与G4证明实际按此同一平均适配。',r'A defined average requires0≤m≤|R|. Each context difference includes dividends I(Lij) of several support orders |L|+2, with0≤|L|≤m. An m-order context interaction therefore does not select a single concept order. The Section F definition and G.4 proof are adapted to this same average.')
material('diff-training-similarity','训练概念的符号拆分 Jaccard','Sign-split Jaccard of learned concepts',r'\operatorname{sim}(I_t,I_f)=\|\min(\widetilde I_t,\widetilde I_f)\|_1/\|\max(\widetilde I_t,\widetilde I_f)\|_1',r'同一阶s的全部支持按同一顺序排列，I_t与I_f分别为中间/最后训练epoch的交互向量；正负两块分别非负。',r'Order-s supports have an identical coordinate order. I_t and I_f are dividend vectors at an intermediate and final epoch; their positive and negative blocks are nonnegative.',r'先按源公式作[maximum(I,0),−minimum(I,0)]符号拆分，再逐坐标min/max取L1比值。这样反号贡献不因抵消显得相似。两向量皆零时分母零。公式在正文未编号；不存在作者Eq10/11别名。图5的早期高相似度是有限实验观察。',r'First split signs as [maximum(I,0),−minimum(I,0)], then take the L1 ratio of coordinatewise minima and maxima. Opposite signs cannot cancel into apparent similarity. Two zero vectors give a zero denominator. The main formulas are unnumbered, with no author Eq. (10)/(11) aliases. High early similarity in Figure5 is a finite experimental observation.')
material('diff-adversarial-metric','对抗绝对变化指标','Absolute-change metric under adversarial attacks',r'\alpha(S)=E_x|I(S\mid x+\delta)-I(S\mid x)|/E_x|I(S\mid x)|,\quad A^{(s)}=E_{|S|=s}\alpha(S)',r'δ是对每个输入生成的ℓ∞攻击；它不是独立Gaussianε。',r'Delta is the per-input ℓ∞ attack, rather than an independent Gaussian epsilon.',r'先对数据平均绝对交互变化，再除以平均幅值，最后对同阶概念平均。没有把攻击随机性自动替换成Gaussian；κ与α的扰动模型不同。图6低阶更鲁棒的经验趋势保留，指标定义不提供任意攻击的鲁棒性概率界。',r'Average absolute dividend changes across data, divide by the mean magnitude, and then average across same-order concepts. The attack is not automatically replaced by Gaussian noise; alpha and kappa have distinct perturbation models. Retain Figure6’s empirical low-order robustness trend without inventing a robustness probability bound against every attack.')
material('diff-experiments','完整正式实验与文献页','The complete formal experiment and literature pages',r'\sigma_{experiment}=0.02',r'正文MLP/AlexNet/VGG/ResNet等按源数据与训练配置比较；C/E/H含实现与补充图；A/B为文献，11–13页为参考文献。',r'The main MLP/AlexNet/VGG/ResNet comparisons follow their source data and training settings. C/E/H contain implementation details and additional plots; A/B review literature and pages11–13 are bibliography.',r'正文噪声实验采用σ=.02；κ机器反例的显式σ是另一个允许模型参数，不冒充复现实验值。所有22物理页，包括无证明图表/参考页均有独立页台账。各指标、数学等号和未编号推理已有单独入口；经验配置仅作来源材料。',r'The main noise experiment uses σ=.02. The explicit machine-counterexample sigma is another allowed model parameter and is not a reproduction of the experiment value. All22 physical pages, including figures and references without proofs, have individual inventory records. Metrics, mathematical equalities and unnumbered arguments have separate entries; experimental configurations remain source material.')
# Qualitative unnumbered arguments: preserve their actual premise-to-conclusion relation.
def inference(i,zt,et,zd,ed,zstep,estep,zwhy,ewhy):
 add(i,zt,et,r'\text{qualitative source inference; no quantified rate theorem}',zd,ed,'保留作者外引/近似措辞；没有额外量化条件或通用学习算法假设。','Retain the cited and approximate wording; no additional quantified conditions or universal learning-algorithm premises are supplied.',[(zt,et,zstep,estep),('核查结论的适用范围','Check the conclusion’s scope',zwhy,ewhy)],role='statement_scope_explanation',assessment='scope_under_review')
inference('diff-learning-consistency-argument','一致性到学习难度的解释','From consistency to learning difficulty','固定特征C、可优化线性权重w、类别样本和输入噪声是不同对象。','Fixed feature C, optimized linear weight w, class samples and input noise are distinct objects.','原作者以稳定出现/缺席解释易学，再由Thm3高阶不稳定推高阶难学。正方差固定特征平方回归真正最优w依赖μ/d，但不等价于迭代学习速度或任意DNN可学习性。','The author interprets stable presence/absence as ease of learning, then invokes Theorem3 to infer higher-order difficulty. The actual fixed-feature squared-loss optimum depends on μ/d; it is not an iteration-rate theorem or learnability theorem for arbitrary DNNs.','原J矩、整体I方差与回归Step3问题分别链接；即使修复有效回归最优，也没有训练动态、更新规则、收敛率或人类概念难度的数学定义，故不报整体普遍学习定理。','The J moments, whole-dividend variance and regression Step3 have separate issues. Repairing the valid optimum still supplies no training dynamics, update rule, convergence rate or mathematical definition of human cognitive difficulty; no universal learning theorem is reported.')
inference('diff-fast-learning-inference','概念一致性到快学的解释','From concept consistency to faster learning','比较中间epoch的交互向量与最终epoch的相同支持向量。','Compare the same support coordinates at an intermediate and final epoch.','原文从3.2的稳定/一致性解释低阶易学，随后用图5早期Jaccard较高支持低阶学得更快。','The source interprets stability/consistency from3.2 as easier learning and then uses higher early Jaccard similarity in Figure5 to support faster learning of low-order concepts.','Jaccard只是已训练向量相似度；未给从噪声稳定度到达到阈值epoch的定理。有限图5支持源经验倾向，但没有统一收敛速度结论。','Jaccard measures similarity of trained vectors. No theorem connects noise stability to the epoch when a threshold is reached. The finite plot supports the empirical tendency without giving a uniform convergence-speed result.')
inference('diff-adversarial-inference','多阶关系到概念鲁棒性的解释','From multiorder relations to concept robustness','原外引[43]上下文多阶交互和本篇支持概念不是同一对象。','Reference[43] context-averaged interactions differ from this paper’s support concepts.','原文利用本篇概念为外引多阶交互的基本分量，解释低阶概念鲁棒性。G4正确上下文差分确可写成多种支持交互和，错误最终Eq25另列。','The source uses concepts as elementary components of cited multiorder interactions to interpret low-order robustness. G.4’s correct context difference decomposes into dividends of several support sizes; its erroneous final Eq. (25) is separate.','上下文平均的大小或稳定性不能自动逐项传递给每个分量；反号可相消且不同支持阶数混合。源图6用真实攻击指标验证有限模型，不是代数分解单独证明任意概念鲁棒。','Magnitude or stability of a context average does not automatically transfer to every component: signed terms can cancel and several support orders are mixed. Figure6 tests finite models under actual attacks; decomposition alone does not establish arbitrary-concept robustness.')
inference('diff-noise-learning-inference','白噪声记忆慢学的解释','Concept interpretation of slow white-noise memorization','[5]比较正常/随机标记白噪声样本，[8]被引用为噪声分类依赖高阶概念。','Reference[5] compares normal and randomly labeled white-noise data;[8] is cited for high-order concepts in noisy-data classification.','作者把外引噪声样本依赖高阶的结论与本篇高阶难学连接，解释白噪声准确率提高较晚。','The source combines cited high-order dependence of noisy data with this paper’s difficulty interpretation to explain later accuracy gains on white noise.','本篇未转录[8]完整条件，也未给准确率随epoch的概率/速率模型；故保留外引条件适配待查与近似解释，不证明所有噪声样本都需要唯一高阶记忆。','The full premises of[8] and an accuracy-versus-epoch rate model are absent here. Retain the cited adaptation and approximate interpretation without proving that every noisy sample requires uniquely high-order memorization.')
inference('diff-shallow-learning-inference','浅模型易样本的解释','Concept interpretation of samples easy for shallow models','[34]按SVM/RF能否正确分类定义easy/hard；这不同于支持阶数定义。','Reference[34] defines easy/hard by correct SVM/RF classification, which differs from support order.','作者claim易样本主要含低阶、难样本主要含高阶，再解释DNN先学易样本。','The source claims easy samples mainly contain low-order concepts and hard samples mainly high-order concepts, then interprets their learning order.','没有将浅模型分类性能等价成交互谱的证明或统一阈值。任意奖励的有限重构也不提供这种数据/模型桥梁；源claim范围保持未量化。','No proof or common threshold equates shallow-model classification with an interaction spectrum. Finite reward reconstruction supplies no such data/model bridge; the source claim remains unquantified.')
inference('diff-frequency-learning-inference','样本空间频谱先后顺序的解释','Interpretation of sample-space spectrum learning order','[63]讨论损失景观/样本空间频率，而F06讨论中间特征二维DFT，两者不同。','Reference[63] concerns loss-landscape/sample-space frequencies, unlike F06’s two-dimensional DFT of intermediate features.','作者经4.1扰动敏感度连接低阶概念与低频、较高阶与高频，用以解释先低频后高频。','The author connects low-order concepts to low frequencies and higher order to higher frequencies through4.1 perturbation sensitivity, interpreting low-before-high frequency learning.','未指定Fourier域、频率阈值、谱能量界及支持阶数到频率的映射。不能直接复用F06特征空间DFT声明，也不把敏感度单独等同于频率；仅保留实际外引解释。','No Fourier domain, frequency threshold, spectral-energy bound or support-order-to-frequency map is specified. F06 feature-space DFT statements cannot be reused directly, and sensitivity alone is not identified with frequency. Retain the actual cited interpretation.')
inference('diff-adversarial-learning-inference','对抗易样本快学的解释','Interpretation of faster adversarial learning on easy samples','[28]比较对抗训练的easy/hard样本损失下降；[43]讨论低阶上下文交互的鲁棒性。','Reference[28] compares adversarial-training loss on easy/hard samples;[43] concerns robustness of low-order context interactions.','作者consider对抗训练易样本may mainly含低阶概念，再结合鲁棒性解释其损失下降更快。','The source considers that adversarially easy samples may mainly contain low-order concepts and combines this with robustness to interpret their faster loss decrease.','原may/roughly措辞不被强化为定理；本篇没有从攻击稳健性到优化下降速度的形式条件，或[28]easy定义与本篇支持概念的完整适配。','The original “may” and “roughly” wording is not strengthened to a theorem. No formal conditions connect attack robustness to optimization speed, and no complete adaptation of[28]’s easy-sample notion to support concepts is supplied.')
# Raw-prefix literal TeX strings: avoid Python converting \tau/\not into control characters.
# Independent bilingual formula review: preserve every intermediate equation and local premise.
EN={
('diff-salient-reconstruction',0):r'Split complete reconstruction into $S\in\Omega$ and $S\notin\Omega$ terms and subtract. This gives the exact residual and $|R_T|\le\sum_{S\subseteq T,S\notin\Omega}|I_g(S)|$. The empty dividend is $I_g(\varnothing)=b$; excluding it from Ω also places it in the residual.',
('diff-taylor',1):r'For a finite polynomial, $m_\pi(z^T)$ is nonzero only when $\operatorname{supp}\pi\subseteq T$, in which case it equals $m_\pi(z)$; otherwise a positive-degree factor is zero. Grouping every degree at its support gives $g(T)=\sum_{S\subseteq T}K_S$. Möbius uniqueness yields $K_S=I_g(S)$, retaining the empty constant. PolynomialSupport uses a finite term index, allowing several degrees with the same support.',
('diff-moments',0):r'$Z\sim\mathcal N(1,q)$ and $E Z=1$. The difference $|Z|-Z\ge0$ is strictly positive on $Z<0$, which has positive Gaussian probability. Therefore $E|Z|=1+E(|Z|-Z)>1$. Lean proves the strict integral positivity through Gaussian/Lebesgue equivalence and continuity of a nonzero function.',
('diff-moments',1):r'Because $|Z|^2=Z^2$ and $EZ^2=1+q$, we obtain $\operatorname{Var}|Z|=1+q-(E|Z|)^2<q$. Source Eq. (5) gives mean1 and varianceq at one-coordinate support, so both exact clauses fail under the full Gaussian model. The formulas hold for signed $Z$, which cannot replace the original J in a proof repair.',
('diff-general-moments',0):r'The affine coordinate $1+s_i\epsilon_i/\tau$ has law N(1,q), with q=σ²/τ². Measurable transformations preserve independence and all finite Gaussian powers are L2. The integral of the product therefore factors into the actual folded moments displayed. The shared Gaussian library discharges these conditions.',
('diff-general-moments',1):r'G.2 Eqs. (14)–(18) replace $|1+s\epsilon/\tau|^{\pi_i}$ by $(1+\epsilon/\tau)^{\pi_i}$ under a small-noise approximation. Odd powers differ on crossing tails; the actual one-coordinate degree1 mean and variance counterexample refutes the exact reading of Eq. (6). Even powers eliminate the absolute value exactly, so not every integer degree is erroneous.',
('diff-product',0):r'Independence gives $E\prod X_i=\prod EX_i$ and $E(\prod X_i)^2=\prod EX_i^2$. Substituting $EX_i^2=(EX_i)^2+\operatorname{Var}X_i$ and subtracting the squared product mean yields the displayed correct variance. Variance itself is not squared.',
('diff-binary',0):r'If $S\subseteq T$, every term needed to compute $I(S)$ has $L\subseteq S$ and hence $L\cap T=L$, so its dividend is unchanged. Otherwise take $i\in S\setminus T$. Inserting $i$ changes no reward of the further-masked game, and dummy cancellation gives $I_{g_T}(S)=0$. Therefore $I_{g_T}(S)=\mathbf1_{S\subseteq T}I_g(S)$, preserving an arbitrary output baseline.',
('diff-binary',2):r'The inactive branch is $S\not\subseteq T$, which supplies $j\in S\setminus T$. This differs from the source printed $S\subsetneq T$. Actual masked-game support proves the binary conclusion on its nonzero domain. Source Eqs. (21)/(24) alternate $r_i/b_i$; the rewrite uses one input baseline r.',
('diff-linear-representation',1):r'For $U_S\ne0$ define $C_S(x\prime)=I_h(S)/U_S$, giving $U_SC_S=I_h(S)$ termwise. Substitution yields linear reconstruction. A legitimate Taylor sum agrees with this ratio, but unrestricted Theorem2 cannot repair an illegitimate expansion. Regression holds the features $C_S$ fixed rather than varying them together with optimized $U_S$.',
('diff-multiorder',0):r'Reconstruct the four game values and cancel all terms except those containing i and j. This yields $\Delta g(i,j,S)=\sum_{L\subseteq S}I_g(L\cup\{i,j\})$. Lean derives this from higherMarginal reconstruction and takes the exact average over every size-m context.',
('diff-regression',0):r'The actual loss is $L(w)=E(y^*-w^\top f)^2=(y^*-\mu^\top w)^2+\sum_i d_iw_i^2$, since covariances of distinct features vanish. Its gradient is $2(Kw-y^*\mu)$. The Gaussian laws establish actual means and second moments rather than assuming the expectation identities.',
}
for (i,j),e in EN.items():s=R[i]['steps'][j];R[i]['steps'][j]=(s[0],s[1],s[2],e)
A={
'efficiency':('N有限，g:2^N→ℝ任意，b=g(∅)任意。','N is finite, g:2^N→ℝ is arbitrary, and b=g(empty) is arbitrary.'),
'linearity':('相同总体的实游戏g,h；合并游戏逐掩码定义为g+h。','Real games g,h have the same universe; their merged game is g+h at every mask.'),
'dummy':(r'i∈N，∅≠S⊊N\{i}；∀U⊆N\{i},g(Ui)=g(U)+g({i})。',r'i∈N, nonempty strict S⊊N\{i}; g(Ui)=g(U)+g({i}) for every U⊆N\{i}.'),
'symmetry':(r'i,j∈N且S⊆N\{i,j}；∀U⊆N\{i,j},g(Ui)=g(Uj)。',r'i,j∈N and S⊆N\{i,j}; g(Ui)=g(Uj) for every U⊆N\{i,j}.'),
'anonymity':('π为N上的双射，重命名奖励满足(πg)(πS)=g(S)。','π is a bijection of N, with relabeled reward (πg)(πS)=g(S).'),
'recursion':(r'i∈N，S⊆N\{i}；强制出现游戏为U↦g(Ui)。',r'i∈N and S⊆N\{i}; the forced-present game is U↦g(Ui).'),
'distribution':('固定支持A⊆N、实幅值c；g(T)=c当A⊆T，否则0。','Fix support A⊆N and real amplitude c; g(T)=c when A⊆T and0 otherwise.')}
for k,a in A.items():R['diff-'+k]['assumptions']=a
# Final source alignment: false source clauses remain the displayed claims.
R['diff-moments']['title']='正文最低阶 J 矩的完整 Gaussian 反例'
R['diff-moments']['title_en']='Full-Gaussian counterexample to the main-text lowest-J moments'
R['diff-moments']['statement_tex']=r'E_\epsilon J(S,\widehat\pi\mid x+\epsilon)=1,\qquad \operatorname{Var}_\epsilon J(S,\widehat\pi\mid x+\epsilon)=\left(1+(\sigma/\tau)^2\right)^{|S|}-1'
R['diff-general-moments']['statement_tex']=r'E_\epsilon J(S,\pi\mid x+\epsilon)=E_\epsilon\prod_{i\in S}(1+\epsilon_i/\tau)^{\pi_i},\quad \operatorname{Var}_\epsilon J(S,\pi\mid x+\epsilon)=\operatorname{Var}_\epsilon\prod_{i\in S}(1+\epsilon_i/\tau)^{\pi_i}'
R['diff-product']['statement_tex']=r'E\prod_iX_i=\prod_iEX_i,\quad\operatorname{Var}\prod_iX_i=\prod_i\big((EX_i)^2+(\operatorname{Var}X_i)^2\big)-\prod_i(EX_i)^2'
R['diff-multiorder']['statement_tex']=r'I^{(m)}(i,j)=\sum_{l=0}^m\frac{\binom{n-2}{m-l}}{\binom{n-2}m}\sum_{L\subseteq N\setminus\{i,j\},\,|L|=m}I(L\cup\{i,j\})'
R['diff-kappa-conversion']['statement_tex']=r'\kappa(S)=\frac{E_xE_\epsilon|I(S\mid x+\epsilon)-I(S\mid x)|}{E_x|I(S\mid x)|}=\frac{E_xE_\epsilon|C_x(x+\epsilon)-C_x(x)|}{E_x|C_x(x)|}'
R['diff-regression']['statement_tex']=r'\mathcal L(w)=\tfrac12E(w^\top f-y^*)^2,\qquad |w_i^*|\propto|1/\sigma_i^2|\quad\text{(source Step 3)}'
for i in ['diff-moments','diff-general-moments','diff-product','diff-multiorder','diff-kappa-conversion','diff-regression']:
 z,e=R[i]['definitions'];R[i]['definitions']=(r'顶部公式保留作者主张；下面明确分开反例、有效子句及独立修正恒等式。'+z,r'The top formula retains the author’s claim. The steps distinguish counterexamples, valid clauses and separately repaired identities. '+e)
# F10 Eq.(9) is on PDF6 and follows Eq.(3), not F08 Eq.(14).
R['diff-linear-representation']['steps'][0]=('先重构当前掩码游戏','First reconstruct the current masked game',r'固定当前输入 $x\prime$ 与参考 $r$，定义 $h(T)=v(x\prime_T)$。正文 PDF6 的 Eq.(9) 由本篇 Eq.(3) 的全支持重构及 Eq.(7) 的 $I_h(S)=U_SC_S(x\prime)$ 得到。先用有限 Möbius 重构 $h(N)=\sum_{S\subseteq N}I_h(S)$；空项仍是 $I_h(\varnothing)=h(\varnothing)$，不假设输出基线为零。',r'Fix the current input $x\prime$ and reference $r$, defining $h(T)=v(x\prime_T)$. Eq. (9) on PDF6 follows from this paper’s complete reconstruction Eq. (3) and $I_h(S)=U_SC_S(x\prime)$ in Eq. (7). Finite Möbius reconstruction gives $h(N)=\sum_{S\subseteq N}I_h(S)$, retaining $I_h(\varnothing)=h(\varnothing)$ without a zero output baseline.')
# Explicit counting bijection, not an engineering scope placeholder.
R['diff-multiorder']['steps'][1]=('双射计数后交换并按阶分组','Count by a bijection, then exchange sums and group by size',r'固定 $L\subseteq R$、$|L|=l\le m$。映射 $S\mapsto S\setminus L$ 把包含 $L$ 的 $m$ 元上下文双射到 $R\setminus L$ 的 $(m-l)$ 元子集，逆映射是 $W\mapsto L\cup W$。因此出现次数为 $\binom{|R|-l}{m-l}=\binom{n-2-l}{m-l}$。交换两个有限和，再把 $L$ 按基数分组，得到下面独立列出的正确恒等式。公共 DifficultyCounting 证明双射、每项出现次数、有限和交换和基数分组；论文适配证明 $|N\setminus\{i,j\}|=n-2$。原 Eq.(25) 的内层下标与系数都保持原样并由下一步反例否定。',r'Fix $L\subseteq R$ with $|L|=l\le m$. The map $S\mapsto S\setminus L$ bijects size-$m$ contexts containing $L$ with size-$(m-l)$ subsets of $R\setminus L$; its inverse is $W\mapsto L\cup W$. Thus the multiplicity is $\binom{|R|-l}{m-l}=\binom{n-2-l}{m-l}$. Exchange the two finite sums and group $L$ by cardinality to obtain the separately displayed correct identity below. DifficultyCounting proves the bijection, multiplicities, sum exchange and cardinality grouping; the paper adapter proves $|N\setminus\{i,j\}|=n-2$. Both original errors in Eq. (25) remain unchanged and are refuted in the next step.')
R['diff-regression']['steps'][0]=('连接原半损失与真实期望','Connect the source half loss to the actual expectation',r'原 Eq.(26) 是 $\mathcal L=\frac12 E(w^\top f-y^*)^2$。为调用公共库，令 $L=2\mathcal L$；正因子不改变严格比较或唯一 argmin。两两独立的有限二阶矩特征满足 $L(w)=(y^*-\mu^\top w)^2+\sum_i d_iw_i^2$，因为非对角协方差为零。故 $K=\mu\mu^\top+\operatorname{diag}d$，原半损失的梯度是 $Kw-y^*\mu$。实际 Gaussian 法则证明均值与二阶矩，而不把期望等式放入假设。',r'Source Eq. (26) is $\mathcal L=\frac12 E(w^\top f-y^*)^2$. Set $L=2\mathcal L$ to use the public library; a positive factor preserves strict comparisons and the unique argmin. Pairwise independent features with finite second moments satisfy $L(w)=(y^*-\mu^\top w)^2+\sum_i d_iw_i^2$, since off-diagonal covariances vanish. Therefore $K=\mu\mu^\top+\operatorname{diag}d$ and the source half-loss gradient is $Kw-y^*\mu$. Actual Gaussian laws establish the means and second moments instead of assuming those expectation identities.')
R['diff-regression']['steps'][1]=('用正定正规方程连接 Cramer 与闭式最优','Connect Cramer and the closed optimum through positive definite normal equations',r'令 $H=1+\sum_j\mu_j^2/d_j>0$，$w_i^*=y^*\mu_i/(d_iH)$。直接验算 $Kw^*=y^*\mu$。对 $z\ne0$，$z^\top Kz=(\mu^\top z)^2+\sum_i d_iz_i^2>0$，故 $\det K>0$ 且 $L(w)-L(w^*)=(w-w^*)^\top K(w-w^*)>0$。原 Eq.(27) 的换列行列式表达是同一正规方程的 Cramer 解，实际适配已连接该式与唯一最优。比值 $|w_i^*|/|w_j^*|=|\mu_i/d_i|/|\mu_j/d_j|$ 需分母非零；当 $\sigma_i^2$ 表示真实方差 $d_i$ 时，它给原 Step2。若按原 $\Sigma=\operatorname{diag}(\sigma_i^2)$、$\operatorname{Cov}f=\Sigma^2$ 字面读，$d_i=\sigma_i^4$，原 Eq.(28) 亦不能无条件称正确。两种读法都不能从 Step2 删除均值。',r'Let $H=1+\sum_j\mu_j^2/d_j>0$ and $w_i^*=y^*\mu_i/(d_iH)$; verify $Kw^*=y^*\mu$. For $z\ne0$, $z^\top Kz=(\mu^\top z)^2+\sum_i d_iz_i^2>0$, so $\det K>0$ and $L(w)-L(w^*)=(w-w^*)^\top K(w-w^*)>0$. The column-replacement determinant in source Eq. (27) is Cramer’s solution of this same normal equation; the actual adapter connects it to the unique optimum. The ratio $|w_i^*|/|w_j^*|=|\mu_i/d_i|/|\mu_j/d_j|$ requires a nonzero denominator and gives source Step2 when $\sigma_i^2$ means the true variance $d_i$. Under the literal notation $\Sigma=\operatorname{diag}(\sigma_i^2)$ and $\operatorname{Cov}f=\Sigma^2$, however, $d_i=\sigma_i^4$ and source Eq. (28) is not generally correct either. Neither reading permits dropping the means.')
z,e=R['diff-recursion']['steps'][0][2:];z=z.replace('附录Eq2与正文Eq2不合并编号。','此递归式在 Appendix D 未编号，不造 Eq.(2) 别名。');e=e.replace('Appendix Eq. (2) is a local alias distinct from main Eq. (2).','This Appendix D recursion is unnumbered, so no Eq. (2) alias is created.');s=R['diff-recursion']['steps'][0];R['diff-recursion']['steps'][0]=(s[0],s[1],z,e)
add('diff-lowest-interaction','附录 G2 最低阶 I 显式变体与真实矩','The appendix G.2 lowest-I variant and its actual moments',r'E_\epsilon I(S\mid x+\epsilon)=U_{S,\widehat\pi},\quad\operatorname{Var}_\epsilon I(S\mid x+\epsilon)=U_{S,\widehat\pi}^2\left[\left(1+(\sigma/\tau)^2\right)^{|S|}-1\right]',
 r'G2 PDF18 的 prose 仍说 $J$，但其显示式写 $I$ 并带 $U_{S,\widehat\pi}$；不同于正文 PDF5 Eq.(5) 的 $J$ 矩。定义真实最低支持单项式 $v(z)=b+a\prod_{i\in S}(z_i-r_i)$，$S\ne\varnothing$，输出基线 $b$ 任意。固定参考增量 $x_i-r_i=s_i\tau$，$s_i\in\{-1,1\}$，固定系数 $U_{ref}=a\prod_i s_i\tau$。',r'On PDF18, G.2 prose still names $J$, whereas the display uses $I$ and $U_{S,\widehat\pi}$, unlike main PDF5 Eq. (5)’s J moments. Define the actual lowest-support monomial $v(z)=b+a\prod_{i\in S}(z_i-r_i)$ for nonempty $S$, with arbitrary output baseline $b$. Fix $x_i-r_i=s_i\tau$, $s_i\in\{-1,1\}$ and the reference coefficient $U_{ref}=a\prod_i s_i\tau$.',
 r'有限非空支持、真实最低单项式、$\tau\ne0$；可测独立坐标 $\epsilon_i\sim\mathcal N(0,\sigma^2)$。不把任意 DNN 的高次项默认删除，也不把原随 $x\prime$ 符号变化的 $U_{S,\widehat\pi}$ 自动视为固定。',r'Use a finite nonempty support, an actual lowest monomial and $\tau\ne0$, with measurable independent coordinates $\epsilon_i\sim\mathcal N(0,\sigma^2)$. Higher terms of an arbitrary DNN are not silently discarded, nor is the source coefficient with signs varying in $x\prime$ silently treated as fixed.',[
 ('从实际掩码单项式提取最低交互','Extract the lowest dividend from the actual masked monomial',r'在掩码 $T$ 下，$g(T)=b+a\prod_i\mathbf1_{i\in T}(x_i-r_i)$；非空完整支持的交互为 $a\prod_i(x_i-r_i)$，常数 $b$ 只贡献空交互。因此加入噪声后的真实交互是 $I_\epsilon=a\prod_i(s_i\tau+\epsilon_i)=U_{ref}\prod_i(1+s_i\epsilon_i/\tau)$。这个有符号恒等式对全部 Gaussian 尾部精确成立，越界时单项式符号与原移动 $U$ 的符号相消。',r'At mask $T$, $g(T)=b+a\prod_i\mathbf1_{i\in T}(x_i-r_i)$. Its nonempty full-support dividend is $a\prod_i(x_i-r_i)$; the constant $b$ contributes only the empty dividend. Thus the actual perturbed dividend is $I_\epsilon=a\prod_i(s_i\tau+\epsilon_i)=U_{ref}\prod_i(1+s_i\epsilon_i/\tau)$. This signed identity holds throughout the full Gaussian tails, with the monomial signs canceling the signs in the source moving coefficient.'),
 ('计算真实 Gaussian 矩并限定作者记号解释','Compute actual Gaussian moments and delimit the source notation',r'每因子均值 $1$、二阶矩 $1+\sigma^2/\tau^2$；实际法则、Gaussian L2 及独立性给 $EI_\epsilon=U_{ref}$ 与 $\operatorname{Var}I_\epsilon=U_{ref}^2[(1+\sigma^2/\tau^2)^{|S|}-1]$。PaperDifficulty 的实际 maskedLowest 适配复用共享 Gaussian 积分证明。若 G2 的 $U_{S,\widehat\pi}$ 意指固定参考 $U_{ref}$ 且已限定最低项，则显示式有这一精确证明；若仍采用 Theorem2 随 $x\prime$ 变化的定义或把高阶项加入完整 $I$，该记号/截断范围不能由本类型消除。正文 $J$ 的反例不直接否定此有符号 $I$ 子句。',r'Each factor has mean $1$ and second moment $1+\sigma^2/\tau^2$. The actual Gaussian law, L2 integrability and independence yield $EI_\epsilon=U_{ref}$ and $\operatorname{Var}I_\epsilon=U_{ref}^2[(1+\sigma^2/\tau^2)^{|S|}-1]$. The maskedLowest adapter reuses the shared Gaussian integral proof. If G.2’s $U_{S,\widehat\pi}$ denotes the fixed reference $U_{ref}$ and only the lowest term is retained, this proves its displayed formula exactly. Its moving-$x\prime$ definition and higher-order truncation scope are not discharged by that type. The main-text J counterexample does not directly refute this signed-I clause.')],role='partial_component',assessment='scope_under_review',scope=('真实最低支持单项式的掩码交互与全尾Gaussian矩完整形式化；原prose/J与display/I及固定/移动U歧义另列，不冒充任意DNN完整交互矩。','The actual masked lowest-support monomial and its full-tail Gaussian moments are formalized. The source J-prose/I-display and fixed/moving-U ambiguities remain separate; no moments for arbitrary complete DNN interactions are claimed.'))
